14:  * @notice Reseed re-initializes the Internal Balance of Farmers.
15:  * @dev non Bean assets cannot be transfered to L2, due to the lack of garentee of the asset's Liquidity.
16:  */
17: contract ReseedInternalBalances {
18:     AppStorage internal s;
19:     event InternalBalanceChanged(address indexed user, IERC20 indexed token, int256 delta);
20: 
21:     struct BeanstalkInternalBalance {
22:         address token;
23:         address[] farmers;
24:         uint256[] balances;
25:         uint256 totalInternalBalance;
26:     }
27: 
28:     function init(
29:         BeanstalkInternalBalance calldata beanBalances,
30:         BeanstalkInternalBalance calldata beanEthBalances,
31:         BeanstalkInternalBalance calldata beanWstethBalances,
32:         BeanstalkInternalBalance calldata beanStableBalances,
33:         BeanstalkInternalBalance calldata urBeanBalances,
34:         BeanstalkInternalBalance calldata urBeanLpBalances
35:     ) external {
36:         setInternalBalances(beanBalances);
37:         setInternalBalances(beanEthBalances);
38:         setInternalBalances(beanWstethBalances);
39:         setInternalBalances(beanStableBalances);
40:         setInternalBalances(urBeanBalances);
41:         setInternalBalances(urBeanLpBalances);
42:     }
43: 
44:     function setInternalBalances(BeanstalkInternalBalance calldata internalBalances) internal {
45:         uint256 totalInternalBalance;
46:         for (uint i; i < internalBalances.farmers.length; i++) {
47:             s.accts[internalBalances.farmers[i]].internalTokenBalance[
48:                 IERC20(internalBalances.token)
49:             ] = internalBalances.balances[i];
50:             totalInternalBalance += internalBalances.balances[i];
51:             emit InternalBalanceChanged(
52:                 internalBalances.farmers[i],
53:                 IERC20(internalBalances.token),
54:                 int256(internalBalances.balances[i])
55:             );
56:         }
57: 
58:         require(
59:             totalInternalBalance == internalBalances.totalInternalBalance,
60:             "ReseedInternalBalances: totalInternalBalance mismatch"
61:         );
62: 
63:         s.sys.internalTokenBalanceTotal[IERC20(internalBalances.token)] = totalInternalBalance;
64:     }
65: }
